import{z as i,x as B,o as e,c as d,q as s,j as t,D as E,d as r,s as o,S as A,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Transfusion","description":"","frontmatter":{"title":"Transfusion","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/transfusion.md","filePath":"llm/transfusion.md","lastUpdated":1791063341000}'),m={name:"llm/transfusion.md"};function f(p,a,u,h,C,T){const n=B("Mermaid");return e(),d("div",null,[a[2]||(a[2]=s('<h1 id="transfusion" tabindex="-1">Transfusion <a class="header-anchor" href="#transfusion" aria-label="Permalink to &quot;Transfusion&quot;">​</a></h1><div class="epigraph"><p>不必为图像另开一套网。同一 Transformer 对文本做下一词交叉熵，对图像潜变量做扩散损失，一次前向里两种目标。</p><footer>—— Zhou 等 Transfusion: Predict the Next Token and Diffuse Images with One Multi-Modal Model</footer></div><p><a href="/llm/unified-understanding-generation">上一课</a>用双塔或混合离散目标缝理解与生成。缺口是连续图像与离散文本在同层注意力里共存：文本是词表，图是 <a href="/llm/latent-vae">潜空间 VAE</a> 的 \\(z\\)。Transfusion 把扩散训练塞进语言模型前向。后课蒸馏默认：图像支路仍可能要多步采样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯离散统一（Chameleon）付 VQ 税。纯连续理解（LLaVA）没有像素生成头。若图像用独立扩散模型，权重不共享，谈图与造图的表征会分叉。Transfusion 的序列是文本 token 与噪声潜补丁交错；注意力按模态用因果（文本）或双向（图像块）掩码。损失是 \\(\\mathcal{L}_{\\mathrm{CE}}+\\lambda\\mathcal{L}_{\\mathrm{diff}}\\)。</p><p><span class="marginnote">直觉类比：把输入序列想成一份图文混排文档。文字从左到右逐字读（因果掩码）；插图部分允许来回看（双向掩码），而且这块「画布」一开始是涂了噪点的，模型一边读文字一边把它涂清楚。</span></p><p>这与 <a href="/llm/cfg-image">CFG</a> 兼容：图像位置走扩散采样，文本仍自回归。</p><p><span class="marginnote">掩码设计是正确性来源：图像段内部可双向，但对文本因果——图像不看未来的文本，而图像之后的文本看得到（加噪的）图像，图生文必需。实现必须按论文设置，否则扩散训练时学到的可见集与推理对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VAE 编码图像到潜补丁，加噪后当连续嵌入送入 Transformer（线性映到模型维）。文本位置出 logits；图像位置出噪声预测。训练混合纯文本、文生图、图生文。推理：文生图从噪声 \\(z_T\\) 多步更新图像槽，同时可读文本前缀。</p><p><span class="marginnote">术语翻译：扩散训练就是「先弄脏再考还原」——把干净图像潜变量 \\(z_0\\) 加随机噪声得到 \\(z_t\\)，让模型看着 \\(z_t\\) 猜加进来的噪声是什么。猜得准，反着一步步减噪声，就能从纯噪声还原出一张图。</span></p>',11)),(e(),t(A,null,{default:E(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%20token%22%5D%20--%3E%20TR%5B%22%E5%90%8C%E4%B8%80%20Transformer%22%5D%0A%20%20ZT%5B%22%E5%99%AA%E5%A3%B0%E6%BD%9C%E8%A1%A5%E4%B8%81%22%5D%20--%3E%20TR%0A%20%20TR%20--%3E%20CE%5B%22%E4%B8%8B%E4%B8%80%E8%AF%8D%20CE%22%5D%0A%20%20TR%20--%3E%20DIFF%5B%22%E6%89%A9%E6%95%A3%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[r("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(e(),t(A,null,{default:E(()=>[o(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E4%B8%80%E4%B8%AA%20batch%EF%BC%9A%E6%96%87%E6%9C%AC%E6%AE%B5%20%2B%20%E5%9B%BE%E5%83%8F%E6%AE%B5%E4%BA%A4%E9%94%99%22%5D%20--%3E%20MASK%7B%22%E6%8C%89%E6%A8%A1%E6%80%81%E9%80%89%E6%8E%A9%E7%A0%81%22%7D%0A%20%20MASK%20--%3E%7C%22%E6%96%87%E6%9C%AC%EF%BC%9A%E5%8F%AA%E7%9C%8B%E8%BF%87%E5%8E%BB%22%7C%20CE%5B%22%E4%B8%8B%E4%B8%80%E8%AF%8D%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20MASK%20--%3E%7C%22%E5%9B%BE%E5%83%8F%E6%AE%B5%E5%86%85%EF%BC%9A%E5%8F%8C%E5%90%91%22%7C%20DIFF%5B%22%E6%89%A9%E6%95%A3%E5%99%AA%E5%A3%B0%E9%A2%84%E6%B5%8B%22%5D%0A%20%20CE%20--%3E%20SUM%5B%22%E6%80%BB%E6%8D%9F%E5%A4%B1%20%3D%20CE%20%2B%20%CE%BB%C2%B7%E6%89%A9%E6%95%A3%22%5D%0A%20%20DIFF%20--%3E%20SUM%0A%20%20SUM%20--%3E%20LAMBDA%7B%22%CE%BB%20%E6%8B%A8%E5%90%91%E5%93%AA%E8%BE%B9%22%7D%0A%20%20LAMBDA%20--%3E%7C%22%E8%BF%87%E5%A4%A7%22%7C%20B1%5B%22%E8%AF%AD%E8%A8%80%E8%83%BD%E5%8A%9B%E8%A2%AB%E5%99%AA%E5%A3%B0%E6%A2%AF%E5%BA%A6%E5%B8%A6%E5%81%8F%22%5D%0A%20%20LAMBDA%20--%3E%7C%22%E8%BF%87%E5%B0%8F%22%7C%20B2%5B%22%E6%96%87%E7%94%9F%E5%9B%BE%E4%B8%8D%E6%94%B6%E6%95%9B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>共享层让文本条件直接活在每层键值里，不必另接交叉注意力适配器。扩散损失给连续槽稠密梯度，CE 给离散槽。\\(\\lambda\\) 决定谁主导：过大则语言模型被图像噪声带偏，过小则文生图不收敛。这是统一训练的主旋钮，不是架构点缀。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多步扩散仍贵。下一课把步数压下去，不改「两种损失可以共存」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Transfusion 在同一 Transformer 里混合 CE 与扩散。</li><li>图像走连续潜补丁，文本走词表。</li><li>注意力掩码必须按模态分因果/双向。</li><li>出处：Zhou 等 Transfusion。</li></ul>',5))])}const c=i(m,[["render",f]]);export{_ as __pageData,c as default};
